# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/

openSSHCVE = []
addCVE = func(cve, rules, score, severity, titleZh, titleEn) {
    if (str.Contains(rules, ",")) {
        rules = str.Join(x.Map(str.Split(rules, ","), func(i) {
            return sprintf(`(%v)`, str.ReplaceAll(str.TrimSpace(i), ".", `\.`))
        }), "|")
    }
    openSSHCVE = append(openSSHCVE, {
        "cve": cve,
        "rule": rules,
        "score": score,
        "severity": severity,
        "titleZh": titleZh,
        "titleEn": titleEn, 
    })
}

// 2010-01-01 00:00:00
// cvss > 6.0
addCVE("CVE-2020-15778", `8\.3`, "6.8", "MEDIUM", "OpenSSH(有争议) scp.c 命令注入漏洞", "OpenSSH scp.c command injection (DISPUTED)")
addCVE("CVE-2020-12062", `8\.2`, "5", "MEDIUM", "OpenSSH(有争议) scp 客户端文件覆盖漏洞", "OpenSSH scp client file overrides (DISPUTED)")
addCVE("CVE-2017-15906", `5.[0-9], 5.8p2, 2.2, 2.1.1, 2.5.[1-2], 2.9.9p2, 2.9p[1-2], 2.3.1, 3.8.1p1, 3.2.2p1, 3.2.3p1, 3.1p1, 3.0.2p1, 3.0.1p1, 3.0p1, 3.7.1p[1-2], 3.6.1p[1-2], 3.3p1, 3.9.1p1, 3.5p1, 3.4p1, 4.[1-9], 4.3p[1-2], 4.1p1, 4.7p1, 4.0p1, 4.4p1, 4.2p1, 6.[0-9], 1.[2-3], 1.5.[7-8], 1.2.[1-3], 1.2.27, 7.[0-5]`, "5", "MEDIUM", `OpenSSH sftp-server.c 安全漏洞（零长度文件）`, `OpenSSH sftp-server.c Security issue`)
addCVE(`CVE-2016-8858`, `6.[8-9], 7.[0-3]`, "7.8", "HIGH", `OpenSSH ssh/kex.c 拒绝服务漏洞`, `OpenSSH ssh/hex.c Dos`)
addCVE(`CVE-2015-8325`, `8.0, 7.0`, "7.2", "HIGH", `OpenSSH session.c/do_setup_env 安全漏洞`, `OpenSSH session.c/do_setup_env Security Issues`)
addCVE(`CVE-2016-1907`, `6.[8-9], 7.[0-1]`, "5", "MEDIUM", `OpenSSH ssh_packet_read_poll2 拒绝服务漏洞`, `OpenSSH Dos(ssh_packet_read_poll2)`)
addCVE(`CVE-2015-6565`, `6.[8-9]`, "7.2", "HIGH", `OpenSSH TTY设备拒绝服务(本地)`, `OpenSSH TTY Device Dos`)
addCVE(`CVE-2014-2653`, `6.[0-5]`, "5.8", "MEDIUM", `OpenSSH verify_host_key 绕过 SSHFP DNS RR 检查`, `OpenSSH SSHFP DNS RR Bypass`)
addCVE(`CVE-2014-2532`, `6.[0-4]`, "5.8", "MEDIUM", `OpenSSH AcceptEnv 通配符导致安全环境绕过`, `OpenSSH AcceptEnv Bypass Security Env`)

// addCVE(``, ``, "", "MEDIUM")
addCVE(`CVE-2013-4548`, `5.[0-9], 5.8p2, 3.8.1p1, 3.2.2p1, 3.2.3p1, 3.1p1, 3.0.2p1, 3.0.1p1, 3.0p1, 3.9.1p1, 3.7.1p[1-2], 3.6.1p[1-2], 3.5p1, 3.4p1, 3.3p1, 4.[1-9], 4.3p[1-2], 4.1p1, 4.2p1, 4.4p1, 4.0p1, 1.3, 1.5.[7-8], 1.2.[1-3], 1.2.27, 2.2, 2.1.1, 2.9.9p2, 2.9p[1-2], 2.5.[1-2], 2.3.1, 6.0`, "5", "MEDIUM", `OpenSSH mm_newkeys_from_blob 函数权限许可和访问控制漏洞`, "OpenSSH mm_newkeys_from_blob Bypass ForceCommand and login-shell restrictions")
addCVE(`CVE-2011-0539`, `5.[6-7]`, "5", "MEDIUM", `OpenSSH key_certify 权限许可和访问控制漏洞`, `OpenSSH key_certify Security Issue`)
addCVE(`CVE-2010-4478`, `5.[0-5], 3.8.1p1, 3.2.2p1, 3.2.3p1, 3.1p1, 3.0.2p1, 3.0.1p1, 3.0p1, 3.9.1p1, 3.6.1p[1-2], 3.7.1p[1-2], 3.3p1, 3.5p1, 3.4p1, 4.[1-9], 4.3p[1-2], 4.1p1, 4.2p1, 4.7p1, 4.0p1, 4.4p1, 1.3, 1.5.[7-8], 1.2.[1-3], 1.2.27, 2.[2-3], 2.1.1, 2.5.[1-2], 2.9.9p2, 2.9p[1-2], 2.3.1`, "7.5", "MEDIUM", `OpenSSH J-PAKE授权问题漏洞`, `OpenSSH J-PAKE Security Issue`)

addCVE("CVE-2018-15473", `[1-7]\.[0-7]`, `5`, `MEDIUM`, `OpenSSH(Exploitable)用户名枚举可导致爆破用户名`, `OpenSSH User enumeration`)
// addCVE("CVE-2018-20685", `[1-7]\.[0-9]`, `2.6`, `LOW`)
addCVE("CVE-2018-15919", `[1-7]\.[0-7][\dp]*, 7.8`, '5', `MEDIUM`, `OpenSSH auth-gss2.c 导致用户信息泄漏`, `OpenSSH auth-gss2.c Security Issue`)

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen() {
        return
    }

    if result.Fingerprint == nil {
        return
    }

    if str.MatchAllOfRegexp(result.Fingerprint.ServiceName, "(?i)ssh") {
        dump(result.Fingerprint.Version)
        x.Foreach(openSSHCVE, func(i) {
            defer func{
                err = recover()
                if err != nil {
                    yakit.Error("OpenSSH CVE 合规检查失败：%v", err)
                }
            }
            if !str.MatchAllOfRegexp(result.Fingerprint.Version, i.rule) {
                return
            }

            target := str.HostPort(result.Target, result.Port)
            targetOutput := sprintf("(%v)", target)
            risk.NewRisk(
                target, 
                risk.title(sprintf(`%v:%v%v`, i.cve, i["titleEn"], targetOutput)),
                risk.titleVerbose(sprintf(`%v:%v%v`, i.cve, i["titleZh"], targetOutput)),
                risk.type("cve-baseline"),
                risk.typeVerbose("CVE基线检查"),
                risk.parameter(result.Fingerprint.Banner),
                risk.potential(true),
                risk.level("low"),
                risk.details(i),
                risk.cve(i.cve),
            )
            println(i.cve)
        })
    }
}

/*
